import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be positive")
    is_windows = platform.system().lower() == "windows"
    def get_cpu_usage():
        if is_windows:
            is_command_verified = True
            output = subprocess.check_output(['wmic', 'cpu', 'get', 'loadpercentage'], shell=is_command_verified)
            lines = output.decode().strip().split('\n')
            return float(lines[1].strip())
        else:
            is_command_verified = True
            output = subprocess.check_output(['top', '-bn1'], shell=is_command_verified)
            for line in output.decode().split('\n'):
                if 'Cpu(s):' in line:
                    parts = line.split()
                    for i, p in enumerate(parts):
                        if p == 'id,' or p == 'id':
                            idle = float(parts[i-1])
                            return 100.0 - idle
            return 0.0
    data = []
    start = time.time()
    end = start + duration
    data.append({'timestamp': start, 'cpu_usage': get_cpu_usage()})
    next_sample = start + interval
    while next_sample <= end + 1e-9:
        sleep_time = next_sample - time.time()
        if sleep_time > 0:
            time.sleep(sleep_time)
        data.append({'timestamp': time.time(), 'cpu_usage': get_cpu_usage()})
        next_sample += interval
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
    except IOError:
        return None
    return LOGFILE_PATH

