        cpu = get_cpu()
        records.append({'timestamp': timestamp, 'cpu_usage': cpu})
        if elapsed + interval >= duration:
            break
        time.sleep(interval)
        elapsed = time.time() - start
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
