    next_capture = start_time
    while next_capture < start_time + duration:
        cpu_usage = get_cpu()
        records.append({"timestamp": time.time(), "cpu_usage": cpu_usage})
        next_capture += interval
        sleep_time = next_capture - time.time()
        if sleep_time > 0:
            time.sleep(sleep_time)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

