import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    proc = subprocess.Popen(script_path, shell=True)
    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    init_cpu = p.cpu_times().user + p.cpu_times().system
    init_rss = p.memory_info().rss
    prev_rss = init_rss
    total_mem_inc = 0
    start_time = time.time()
    while True:
        time.sleep(0.1)
        try:
            if not p.is_running():
                break
        except psutil.NoSuchProcess:
            break
        now = time.time()
        elapsed = now - start_time
        if elapsed >= timeout:
            proc.terminate()
            break
        try:
            cur_rss = p.memory_info().rss
            inc = cur_rss - prev_rss
            if inc > 0:
                total_mem_inc += inc
            prev_rss = cur_rss
        except psutil.NoSuchProcess:
            break
    final_cpu = p.cpu_times().user + p.cpu_times().system
    final_time = time.time()
    wall_time = final_time - start_time
    cpu_usage = ((final_cpu - init_cpu) / wall_time) * 100.0 if wall_time > 0 else 0.0
    return {'CPU Usage': cpu_usage, 'Memory Usage': total_mem_inc}

